public sealed class CustomerRepository {          // mapper: SQL + explicit translation
    private readonly IDbConnection _db;

    public Customer? Find(Guid id) =>
        _db.QuerySingleOrDefault<Customer>(
            "SELECT id, name FROM customers WHERE id = @id", new { id });

    public void Rename(Customer c) =>
        _db.Execute("UPDATE customers SET name = @Name WHERE id = @Id", c);
}
